const express = require('express');
const webpush = require('web-push');
const { db } = require('../db');
const { verifyJwt } = require('../middleware');

const app = express();
app.use(express.json());

app.post('/api/tenants/:tenantId/push/vapid-keys/rotate', verifyJwt, async (req, res) => {
  const { tenantId } = req.params;

  // Enforce tenant boundary and require administrative role
  if (req.user.tenantId !== tenantId || req.user.role !== 'TENANT_ADMIN') {
    return res.status(403).json({
      error: 'Access denied: cannot rotate VAPID keys outside your authorized tenant administration'
    });
  }

  const newVapidKeys = webpush.generateVAPIDKeys();

  const updated = await db.query(
    'UPDATE tenant_push_configs SET public_key = $1, private_key = $2, rotated_at = NOW() WHERE tenant_id = $3 RETURNING tenant_id, public_key',
    [newVapidKeys.publicKey, newVapidKeys.privateKey, tenantId]
  );

  if (updated.rowCount === 0) {
    return res.status(404).json({ error: 'Tenant push configuration not found' });
  }

  // Return only the public key in response; private key remains stored securely
  res.json({
    message: 'VAPID keys rotated successfully',
    tenantId: updated.rows[0].tenant_id,
    publicKey: updated.rows[0].public_key
  });
});

app.listen(8101);
